def initial(self, batch_size):
    deter = torch.zeros(batch_size, self._deter, device=self._device)
    if self._discrete:
        state = dict(
            logit=torch.zeros(
                [batch_size, self._stoch, self._discrete], device=self._device
            ),
            stoch=torch.zeros(
                [batch_size, self._stoch, self._discrete], device=self._device
            ),
            deter=deter,
        )
    else:
        state = dict(
            mean=torch.zeros([batch_size, self._stoch], device=self._device),
            std=torch.zeros([batch_size, self._stoch], device=self._device),
            stoch=torch.zeros([batch_size, self._stoch], device=self._device),
            deter=deter,
        )
    if self._initial == "zeros":
        return state
    elif self._initial == "learned":
        state["deter"] = torch.tanh(self.W).repeat(batch_size, 1)
        state["stoch"] = self.get_stoch(state["deter"])
        return state
    else:
        raise NotImplementedError(self._initial)

def observe(self, embed, action, is_first, state=None, dt_labels=None):
    swap = lambda x: x.permute([1, 0] + list(range(2, len(x.shape))))
    # (batch, time, ch) -> (time, batch, ch)
    embed, action, is_first = swap(embed), swap(action), swap(is_first)
    # prev_state[0] means selecting posterior of return(posterior, prior) from obs_step
    if dt_labels is not None:
        dt_labels_t = swap(dt_labels)
        post, prior = tools.static_scan(
            lambda prev_state, prev_act, embed, is_first, dt: self.obs_step(
                prev_state[0], prev_act, embed, is_first, dt=dt
            ),
            (action, embed, is_first, dt_labels_t),
            (state, state),
        )
    else:
        post, prior = tools.static_scan(
            lambda prev_state, prev_act, embed, is_first: self.obs_step(
                prev_state[0], prev_act, embed, is_first
            ),
            (action, embed, is_first),
            (state, state),
        )

    # (batch, time, stoch, discrete_num) -> (batch, time, stoch, discrete_num)
    post = {k: swap(v) for k, v in post.items()}
    prior = {k: swap(v) for k, v in prior.items()}
    return post, prior

def imagine_with_action(self, action, state, dt_sequence=None):
    swap = lambda x: x.permute([1, 0] + list(range(2, len(x.shape))))
    assert isinstance(state, dict), state
    action = swap(action)
    if dt_sequence is not None:
        dt_sequence = swap(dt_sequence)
        prior = tools.static_scan(
            lambda s, a, dt: self.img_step(s, a, dt=dt),
            [action, dt_sequence], state
        )
    else:
        prior = tools.static_scan(self.img_step, [action], state)
    prior = prior[0]
    prior = {k: swap(v) for k, v in prior.items()}
    return prior

def get_feat(self, state):
    stoch = state["stoch"]
    if self._discrete:
        shape = list(stoch.shape[:-2]) + [self._stoch * self._discrete]
        stoch = stoch.reshape(shape)
    return torch.cat([stoch, state["deter"]], -1)

def get_dist(self, state, dtype=None):
    if self._discrete:
        logit = state["logit"]
        dist = torchd.independent.Independent(
            tools.OneHotDist(logit, unimix_ratio=self._unimix_ratio), 1
        )
    else:
        mean, std = state["mean"], state["std"]
        dist = tools.ContDist(
            torchd.independent.Independent(torchd.normal.Normal(mean, std), 1)
        )
    return dist

def obs_step(self, prev_state, prev_action, embed, is_first, dt=None, sample=True):
    # initialize all prev_state
    if prev_state == None or torch.sum(is_first) == len(is_first):
        prev_state = self.initial(len(is_first))
        prev_action = torch.zeros(
            (len(is_first), self._num_actions), device=self._device
        )
    # overwrite the prev_state only where is_first=True
    elif torch.sum(is_first) > 0:
        is_first = is_first[:, None]
        prev_action *= 1.0 - is_first
        init_state = self.initial(len(is_first))
        for key, val in prev_state.items():
            is_first_r = torch.reshape(
                is_first,
                is_first.shape + (1,) * (len(val.shape) - len(is_first.shape)),
            )
            prev_state[key] = (
                val * (1.0 - is_first_r) + init_state[key] * is_first_r
            )

    prior = self.img_step(prev_state, prev_action, dt=dt)
    x = torch.cat([prior["deter"], embed], -1)
    # (batch_size, prior_deter + embed) -> (batch_size, hidden)
    x = self._obs_out_layers(x)
    # (batch_size, hidden) -> (batch_size, stoch, discrete_num)
    stats = self._suff_stats_layer("obs", x)
    if sample:
        stoch = self.get_dist(stats).sample()
    else:
        stoch = self.get_dist(stats).mode()
    post = {"stoch": stoch, "deter": prior["deter"], **stats}
    return post, prior

def img_step(self, prev_state, prev_action, dt=None, sample=True, tcn_sigma=0.0):
    # (batch, stoch, discrete_num)
    prev_stoch = prev_state["stoch"]
    if self._discrete:
        shape = list(prev_stoch.shape[:-2]) + [self._stoch * self._discrete]
        # (batch, stoch, discrete_num) -> (batch, stoch * discrete_num)
        prev_stoch = prev_stoch.reshape(shape)

    if self._dt_embedding is not None:
        if dt is None:
            dt = torch.ones(
                prev_stoch.shape[0], dtype=torch.long,
                device=prev_stoch.device
            )
        dt_emb = self._dt_embedding(dt - 1)
        # TCN: temporal conditioning noise on dt embedding during imagination
        if tcn_sigma > 0:
            dt_emb = dt_emb + tcn_sigma * dt_emb.detach().std() * torch.randn_like(dt_emb)
        x = torch.cat([prev_stoch, prev_action, dt_emb], -1)
    else:
        x = torch.cat([prev_stoch, prev_action], -1)

    # (batch, stoch * discrete_num + action [+ dt_emb]) -> (batch, hidden)
    x = self._img_in_layers(x)
    for _ in range(self._rec_depth):  # rec depth is not correctly implemented
        deter = prev_state["deter"]
        # (batch, hidden), (batch, deter) -> (batch, deter), (batch, deter)
        x, deter = self._cell(x, [deter])
        deter = deter[0]  # Keras wraps the state in a list.
    # (batch, deter) -> (batch, hidden)
    x = self._img_out_layers(x)
    # (batch, hidden) -> (batch_size, stoch, discrete_num)
    stats = self._suff_stats_layer("ims", x)
    if sample:
        stoch = self.get_dist(stats).sample()
    else:
        stoch = self.get_dist(stats).mode()
    prior = {"stoch": stoch, "deter": deter, **stats}
    return prior

def get_stoch(self, deter):
    x = self._img_out_layers(deter)
    stats = self._suff_stats_layer("ims", x)
    dist = self.get_dist(stats)

def save_episodes(directory, episodes):
    directory = pathlib.Path(directory).expanduser()
    directory.mkdir(parents=True, exist_ok=True)
    for filename, episode in episodes.items():
        length = len(episode["reward"])
        filename = directory / f"{filename}-{length}.npz"
        with io.BytesIO() as f1:
            np.savez_compressed(f1, **episode)
            f1.seek(0)
            with filename.open("wb") as f2:
                f2.write(f1.read())
    return True


def from_generator(generator, batch_size):
    while True:
        batch = []
        for _ in range(batch_size):
            batch.append(next(generator))
        data = {}
        for key in batch[0].keys():
            data[key] = []
            for i in range(batch_size):
                data[key].append(batch[i][key])
            data[key] = np.stack(data[key], 0)
        yield data


def sample_episodes(episodes, length, seed=0):
    np_random = np.random.RandomState(seed)
    while True:
        size = 0
        ret = None
        p = np.array(
            [len(next(iter(episode.values()))) for episode in episodes.values()]
        )
        p = p / np.sum(p)
        while size < length:
            episode = np_random.choice(list(episodes.values()), p=p)
            total = len(next(iter(episode.values())))
            # make sure at least one transition included
            if total < 2:
                continue
            if not ret:
                index = int(np_random.randint(0, total - 1))
                ret = {
                    k: v[index : min(index + length, total)].copy()
                    for k, v in episode.items()
                    if "log_" not in k
                }
                if "is_first" in ret:
                    ret["is_first"][0] = True
            else:
                # 'is_first' comes after 'is_last'
                index = 0
                possible = length - size
                ret = {
                    k: np.append(
                        ret[k], v[index : min(index + possible, total)].copy(), axis=0
                    )
                    for k, v in episode.items()
                    if "log_" not in k
                }
                if "is_first" in ret:
                    ret["is_first"][size] = True
            size = len(next(iter(ret.values())))
        yield ret


def load_episodes(directory, limit=None, reverse=True):
    directory = pathlib.Path(directory).expanduser()
    episodes = collections.OrderedDict()
    total = 0
    if reverse:
        for filename in reversed(sorted(directory.glob("*.npz"))):
            try:
                with filename.open("rb") as f:
                    episode = np.load(f)
                    episode = {k: episode[k] for k in episode.keys()}
            except Exception as e:
                print(f"Could not load episode: {e}")
                continue
            # extract only filename without extension
            episodes[str(os.path.splitext(os.path.basename(filename))[0])] = episode
            total += len(episode["reward"]) - 1
            if limit and total >= limit:
                break
    else:
        for filename in sorted(directory.glob("*.npz")):
            try:
                with filename.open("rb") as f:
                    episode = np.load(f)
                    episode = {k: episode[k] for k in episode.keys()}
            except Exception as e:
                print(f"Could not load episode: {e}")
                continue
            episodes[str(filename)] = episode
            total += len(episode["reward"]) - 1
            if limit and total >= limit:
                break
    return episodes


